import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.formrecognizer import DocumentAnalysisClient

def normalize_expense(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint") or os.environ["AZURE_FORM_RECOGNIZER_ENDPOINT"]
    api_key = config.get("api_key") or os.environ["AZURE_FORM_RECOGNIZER_API_KEY"]
    client = DocumentAnalysisClient(endpoint=endpoint, credential=AzureKeyCredential(api_key))
    poller = client.begin_analyze_document("prebuilt-receipt", document=payload)
    analysis = poller.result()
    doc = analysis.documents[0] if analysis.documents else None
    fields = doc.fields if doc else {}

    def _get(field_name):
        f = fields.get(field_name)
        if not f:
            return None
        if getattr(f, "value", None) is not None:
            return f.value
        return f.content

    merchant_name = _get("MerchantName")
    merchant_phone = _get("MerchantPhoneNumber")
    transaction_date = _get("TransactionDate")
    transaction_time = _get("TransactionTime")
    total = _get("Total")
    subtotal = _get("Subtotal")
    tax = _get("TotalTax")
    tip = _get("Tip")
    currency = None

    total_field = fields.get("Total")
    if total_field and getattr(total_field, "value", None) is not None:
        currency = getattr(total_field.value, "currency_symbol", None) or getattr(total_field.value, "currency_code", None)

    items = []
    items_field = fields.get("Items")
    if items_field and getattr(items_field, "value", None):
        for item in items_field.value:
            item_fields = getattr(item, "value", {}) or {}
            def _item_get(name):
                f = item_fields.get(name)
                if not f:
                    return None
                if getattr(f, "value", None) is not None:
                    return f.value
                return f.content
            items.append({
                "description": _item_get("Description"),
                "quantity": _item_get("Quantity"),
                "unit_price": _item_get("Price"),
                "total_price": _item_get("TotalPrice"),
            })

    result = {
        "vendor": {
            "name": merchant_name,
            "phone": merchant_phone,
        },
        "transaction": {
            "date": transaction_date.isoformat() if hasattr(transaction_date, "isoformat") else transaction_date,
            "time": transaction_time.isoformat() if hasattr(transaction_time, "isoformat") else transaction_time,
        },
        "amounts": {
            "subtotal": getattr(subtotal, "amount", subtotal),
            "tax": getattr(tax, "amount", tax),
            "tip": getattr(tip, "amount", tip),
            "total": getattr(total, "amount", total),
            "currency": currency,
        },
        "items": items,
        "provider": {
            "name": "azure-ai-formrecognizer",
            "model": "prebuilt-receipt",
        },
    }
    return result
